// Generated by vibelang from src/features/repo/cloneHeader.ts; the migrate flow writes it again with each batch.
import { mayAsk } from "../auth/contract.js";
import { MEMBERS_CLONE, SIGN_IN_TO_CLONE } from "./contract.js";
/** Clone spends this repository's budget: its role answer, never the session's role, admits the button. */
export const cloneHeaderOf = (header, signedIn, answer) => {
    if (header.kind !== "clone" && header.kind !== "refused")
        return header;
    if (signedIn === false)
        return { kind: "sign_in", text: SIGN_IN_TO_CLONE };
    if (signedIn !== true || answer === undefined)
        return { kind: "unknown" };
    if (answer.failure !== undefined)
        return header.kind === "refused" ? { ...header, retry: false } : { kind: "unknown" };
    return mayAsk(answer.role) ? header : { kind: "refused", text: MEMBERS_CLONE, retry: false };
};
